    44	const McpAppContext = createContext<McpAppApi<unknown>>({
    45		data: null,
    46		toolName: null,
    47		viewState: {},
    48		setViewState: () => {},
    49		callTool: async () => {},
    50		openLink: async () => {},
    51		lastResult: null,
    52		allowSpaHostedViews: false,
    53	});
    54	
    55	/** Typed accessor for the host bridge inside a bundle's card component. */
    56	export function useMcpApp<T>(): McpAppApi<T> {
    57		return useContext(McpAppContext) as McpAppApi<T>;
    58	}
    59	
    60	const isEmbedded = window.parent !== window;
    61	const OPENAI_SET_GLOBALS_EVENT = "openai:set_globals";
    62	
    63	type OpenAiCompatWindow = Window & { openai?: unknown };
    64	type OpenAiSetGlobalsEvent = CustomEvent<{ globals?: unknown }>;
    65	
    66	function openAiCompatTargets(): OpenAiCompatWindow[] {
    67		const ownWindow = window as OpenAiCompatWindow;
    68		if (!isEmbedded) return [ownWindow];
    69		try {
    70			if (window.parent.location.origin === window.location.origin) {
    71				return [ownWindow, window.parent as OpenAiCompatWindow];
    72			}
    73		} catch {
    74			// A cross-origin parent is the standard portable MCP Apps topology.
    75		}
    76		return [ownWindow];
    77	}
    78	
    79	function currentOpenAiGlobals(targets = openAiCompatTargets()): unknown {
    80		let fallback: unknown;
    81		let metadataFallback: unknown;
    82		let widgetStateFallback: unknown;
    83		for (const target of targets) {
    84			const candidate = target.openai;
    85			if (candidate === undefined) continue;
    86			fallback ??= candidate;
    87			if (
    88				isStructuredObject(candidate) &&
    89				Object.hasOwn(candidate, "toolOutput")
    90			) {
    91				return candidate;
    92			}
    93			if (
    94				isStructuredObject(candidate) &&
    95				readOpenAiCompatSnapshot(candidate).data !== undefined
    96			) {
    97				widgetStateFallback ??= candidate;
    98			}
    99			if (
   100				isStructuredObject(candidate) &&
   101				Object.hasOwn(candidate, "toolResponseMetadata")
   102			) {
   103				metadataFallback ??= candidate;
   104			}
   105		}
   106		return widgetStateFallback ?? metadataFallback ?? fallback;
   107	}
   108	
   109	function persistOpenAiData<T>(
   110		targets: OpenAiCompatWindow[],
   111		data: T | null,
   112	): void {
   113		for (const target of targets) {
   114			if (persistOpenAiViewSnapshot(target.openai, data)) return;
   115		}
   116	}
   117	
   118	function hasSameOriginParent(): boolean {
   119		if (!isEmbedded) return true;
   120		try {
   121			return window.parent.location.origin === window.location.origin;
   122		} catch {
   123			return false;
   124		}
   125	}
   126	
   127	function isStructuredObject(value: unknown): value is Record<string, unknown> {
   128		return Boolean(value) && typeof value === "object" && !Array.isArray(value);
   129	}
   130	
   131	function toolInfoFromHostContext(value: unknown): {
   132		id: string | number;
   133		name: string;
   134	} | null {
   135		if (!isStructuredObject(value) || !isStructuredObject(value.toolInfo))
   136			return null;
   137		const id = value.toolInfo.id;
   138		const tool = value.toolInfo.tool;
   139		if (
   140			(typeof id !== "string" && typeof id !== "number") ||
   141			!isStructuredObject(tool) ||
   142			typeof tool.name !== "string"
   143		) {
   144			return null;
   145		}
   146		return { id, name: tool.name };
   147	}
   148	
   149	function snapshotCapabilityFromMeta(value: unknown): string | null {
   150		if (!isStructuredObject(value)) return null;
   151		const capability = value["lobu/mcp-app-snapshot-capability"];
   152		if (typeof capability !== "string") return null;
   153		const normalized = capability.trim();
   154		return normalized && normalized.length <= 512 ? normalized : null;
   155	}
   156	
   157	function restoredViewState(value: unknown): McpAppViewState {
   158		if (!isStructuredObject(value)) return {};
   159		return Object.fromEntries(
   160			Object.entries(value).filter(
   161				(entry): entry is [string, ViewStateValue] =>
   162					typeof entry[1] === "boolean" ||
   163					typeof entry[1] === "string" ||
   164					(typeof entry[1] === "number" && Number.isFinite(entry[1])),
   165			),
   166		);
   167	}
   168	
   169	function applyTheme(theme: "light" | "dark" | undefined): void {
   170		const dark = theme
   171			? theme === "dark"
   172			: window.matchMedia("(prefers-color-scheme: dark)").matches;
   173		document.documentElement.classList.toggle("dark", dark);
   174	}
   175	
   176	export function Provider<T>({
   177		devMock,
   178		children,
   179	}: {
   180		devMock: T;
   181		children: ReactNode;
   182	}) {
   183		const [initialCompat] = useState(() =>
   184			readOpenAiCompatSnapshot<T>(currentOpenAiGlobals()),
   185		);
   186		const [data, setData] = useState<T | null>(
   187			isEmbedded ? (initialCompat.data ?? null) : devMock,
   188		);
   189		const [toolName, setToolName] = useState<string | null>(null);
   190		const [viewState, setViewStateValue] = useState<McpAppViewState>({});
   191		const [lastResult, setLastResult] = useState<{
   192			isError: boolean;
   193			seq: number;
   194		} | null>(null);
   195		const [app, setApp] = useState<App | null>(null);
   196		const [approvalCapability, setApprovalCapability] = useState<string | null>(
   197			initialCompat.approvalCapability ?? null,
   198		);
   199		const hasLiveToolOutput = useRef(false);
   200		const hasData = useRef(data !== null);
   201		const toolCallId = useRef<string | number | null>(null);
   202		const toolCallName = useRef<string | null>(null);
   203		const snapshotCapability = useRef<string | null>(null);
   204		const snapshotBinding = useRef<string | null>(null);
   205		const viewStateRef = useRef<McpAppViewState>({});
   206		const saveStateTimer = useRef<number | null>(null);
   207		const allowSpaHostedViews = hasSameOriginParent();
   208	
   209		useEffect(() => {
   210			if (!isEmbedded) {
   211				applyTheme(undefined);
   212				return;
   213			}
   214	
   215			const compatTargets = openAiCompatTargets();
   216			const nextApp = new App(
   217				{ name: "Lobu Interaction", version: "1.0.0" },
   218				{},
   219				{ autoResize: true, strict: true },
   220			);
   221			const transport = new PostMessageTransport(window.parent, window.parent);
   222			const bindSnapshotToHostCard = async () => {
   223				const capability = snapshotCapability.current;
   224				const id = toolCallId.current;
   225				const name = toolCallName.current;
   226				if (!capability || id === null || !name || snapshotBinding.current)
   227					return;
   228				snapshotBinding.current = capability;
   229				try {
   230					const result = await nextApp.callServerTool({
   231						name: "save_lobu_app_state",
   232						arguments: {
   233							tool_call_id: id,
   234							tool_name: name,
   235							view_state: viewStateRef.current,
   236							snapshot_capability: capability,
   237						},
   238						_meta: { "lobu/mcp-app-snapshot-capability": capability },
   239					});
   240					if (
   241						result.isError !== true &&
   242						isStructuredObject(result.structuredContent) &&
   243						result.structuredContent.saved === true &&
   244						snapshotCapability.current === capability
   245					) {
   246						snapshotCapability.current = null;
   247					}
   248				} catch {
   249					console.warn("[mcp-app] failed to bind result snapshot");
   250				} finally {
   251					if (snapshotBinding.current === capability) {
   252						snapshotBinding.current = null;
   253					}
   254				}
   255			};
   256			const onToolResult = (params: {
   257				structuredContent?: unknown;
   258				_meta?: unknown;
   259			}) => {
   260				if (isStructuredObject(params.structuredContent)) {
   261					const nextData = params.structuredContent as T;
   262					hasLiveToolOutput.current = true;
   263					hasData.current = true;
   264					setData(nextData);
   265					persistOpenAiData(compatTargets, nextData);
   266				}
   267				snapshotCapability.current = snapshotCapabilityFromMeta(params._meta);
   268				void bindSnapshotToHostCard();
   269				setApprovalCapability(approvalCapabilityFromMeta(params._meta));
   270			};
   271			const onHostContext = (params: { theme?: "light" | "dark" }) => {
   272				applyTheme(params.theme);
   273				const info = toolInfoFromHostContext(nextApp.getHostContext());
   274				if (info) {
   275					toolCallId.current = info.id;
   276					toolCallName.current = info.name;
   277					setToolName(info.name);
   278					void bindSnapshotToHostCard();
   279				}
   280			};
   281			const applyOpenAiGlobals = (
   282				globals: unknown,
   283				persistInitialData = false,
   284			) => {
   285				const snapshot = readOpenAiCompatSnapshot<T>(globals);
   286				const includesToolOutput =
   287					isStructuredObject(globals) && Object.hasOwn(globals, "toolOutput");
   288				if (includesToolOutput) hasLiveToolOutput.current = true;
   289				if (snapshot.data !== undefined) {
   290					// setWidgetState echoes a widgetState-only event. Never let that
   291					// display-safe cache replace a live result in the current lifetime.
   292					if (includesToolOutput || !hasLiveToolOutput.current) {
   293						setData(snapshot.data);
   294						hasData.current = snapshot.data !== null;
   295					}
   296					if (persistInitialData || includesToolOutput) {
   297						persistOpenAiData(compatTargets, snapshot.data);
   298					}
   299				}
   300				if (snapshot.approvalCapability !== undefined) {
   301					setApprovalCapability(snapshot.approvalCapability);
   302				}
   303			};
   304			const onOpenAiSetGlobals = (event: Event) => {
   305				const detail = (event as OpenAiSetGlobalsEvent).detail;
   306				if (isStructuredObject(detail) && "globals" in detail) {
   307					applyOpenAiGlobals(detail.globals);
   308				}
   309			};
   310			nextApp.addEventListener("toolresult", onToolResult);
   311			nextApp.addEventListener("hostcontextchanged", onHostContext);
   312			for (const target of compatTargets) {
   313				target.addEventListener(OPENAI_SET_GLOBALS_EVENT, onOpenAiSetGlobals);
   314			}
   315			// Persist preloaded output once. Later compatibility events are read-only:
   316			// setWidgetState itself publishes an openai:set_globals widgetState update.
   317			applyOpenAiGlobals(currentOpenAiGlobals(compatTargets), true);
   318			setApp(nextApp);
   319			void nextApp
   320				.connect(transport)
   321				.then(async () => {
   322					const hostContext = nextApp.getHostContext();
   323					applyTheme(hostContext?.theme);
   324					const info = toolInfoFromHostContext(hostContext);
   325					if (!info) return;
   326					toolCallId.current = info.id;
   327					toolCallName.current = info.name;
   328					setToolName(info.name);
   329					await bindSnapshotToHostCard();
   330					if (hasData.current) return;
   331					const result = await nextApp.callServerTool({
   332						name: "restore_lobu_app_result",
   333						arguments: { tool_call_id: info.id, tool_name: info.name },
   334					});
   335					if (!isStructuredObject(result.structuredContent)) return;
   336					const restored = result.structuredContent;
   337					if (restored.found !== true || !isStructuredObject(restored.data))
   338						return;
   339					const nextData = restored.data as T;
   340					const nextViewState = restoredViewState(restored.view_state);
   341					hasData.current = true;
   342					setData(nextData);
   343					viewStateRef.current = nextViewState;
   344					setViewStateValue(nextViewState);
   345					if (typeof restored.tool_name === "string") {
   346						setToolName(restored.tool_name);
   347					}
   348					persistOpenAiData(compatTargets, nextData);
   349				})
   350				.catch((error) => {
   351					console.error("[mcp-app] failed to initialize", error);
   352				});
   353	
   354			return () => {
   355				nextApp.removeEventListener("toolresult", onToolResult);
   356				nextApp.removeEventListener("hostcontextchanged", onHostContext);
   357				for (const target of compatTargets) {
   358					target.removeEventListener(
   359						OPENAI_SET_GLOBALS_EVENT,
   360						onOpenAiSetGlobals,
   361					);
   362				}
   363				void transport.close();
   364				if (saveStateTimer.current !== null) {
   365					window.clearTimeout(saveStateTimer.current);
   366				}
   367			};
   368		}, []);
   369	
   370		const setViewState = useCallback(
   371			(key: string, value: ViewStateValue) => {
   372				if (!key || key.length > 120) return;
   373				const next = { ...viewStateRef.current, [key]: value };
   374				viewStateRef.current = next;
   375				setViewStateValue(next);
   376				if (!app || toolCallId.current === null || toolCallName.current === null)
   377					return;
   378				if (saveStateTimer.current !== null) {
   379					window.clearTimeout(saveStateTimer.current);
   380				}
   381				saveStateTimer.current = window.setTimeout(() => {
   382					saveStateTimer.current = null;
   383					const capability = snapshotCapability.current;
   384					void app
   385						.callServerTool({
   386							name: "save_lobu_app_state",
   387							arguments: {
   388								tool_call_id: toolCallId.current,
   389								tool_name: toolCallName.current,
   390								view_state: viewStateRef.current,
   391								...(capability
   392									? { snapshot_capability: capability }
   393									: {}),
   394							},
   395							...(capability
   396								? {
   397										_meta: {
   398											"lobu/mcp-app-snapshot-capability": capability,
   399										},
   400									}
   401								: {}),
   402						})
   403						.then((result) => {
   404							if (
   405								capability &&
   406								result.isError !== true &&
   407								isStructuredObject(result.structuredContent) &&
   408								result.structuredContent.saved === true &&
   409								snapshotCapability.current === capability
   410							) {
   411								snapshotCapability.current = null;
   412							}
   413						})
   414						.catch(() => {
   415							console.warn("[mcp-app] failed to save view state");
   416						});
   417				}, 250);
   418			},
   419			[app],
   420		);
   421	
   422		const callTool = async (name: string, args: ToolArgs) => {
   423			if (!app) {
   424				if (!isEmbedded) {
   425					console.log("[mcp-app] tools/call", name, args);
   426					setLastResult((last) => ({
   427						isError: false,
   428						seq: (last?.seq ?? 0) + 1,
   429					}));
   430				}
   431				return;
   432			}
   433			try {
   434				const result = await app.callServerTool({
   435					name,
   436					arguments: args,
   437					...(name === "resolve_lobu_approval" && approvalCapability
   438						? { _meta: { "lobu/approval-capability": approvalCapability } }
   439						: {}),
   440				});
   441				if (isStructuredObject(result.structuredContent)) {
   442					const nextData = result.structuredContent as T;
   443					hasLiveToolOutput.current = true;
   444					hasData.current = true;
   445					setData(nextData);
   446					persistOpenAiData(openAiCompatTargets(), nextData);
   447				}
   448				if (name === "resolve_lobu_approval" && result.isError !== true) {
   449					setApprovalCapability(null);
   450				}
   451				setLastResult((last) => ({
   452					isError: result.isError === true,
   453					seq: (last?.seq ?? 0) + 1,
   454				}));
   455			} catch {
   456				setLastResult((last) => ({
   457					isError: true,
   458					seq: (last?.seq ?? 0) + 1,
   459				}));
   460			}
   461		};
   462	
   463		const openLink = async (href: string) => {
   464			if (!isExternalHttpUrl(href)) {
   465				console.warn("[mcp-app] refused non-HTTP external link");
   466				return;
   467			}
   468			if (!app) {
   469				if (!isEmbedded) console.log("[mcp-app] ui/open-link", href);
   470				return;
   471			}
   472			try {
   473				const result = await app.openLink({ url: href });
   474				if (result.isError) console.warn("[mcp-app] host rejected external link");
   475			} catch {
   476				console.warn("[mcp-app] host rejected external link");
   477			}
   478		};
   479	
   480		return (
   481			<McpAppContext.Provider
   482				value={{
   483					data,
   484					toolName,
   485					viewState,
   486					setViewState,
   487					callTool,
   488					openLink,
   489					lastResult,
   490					allowSpaHostedViews,
   491				}}
   492			>
   493				{children}
   494			</McpAppContext.Provider>
   495		);
   496	}
