   498	/** Mount a bundle's card as a standalone MCP App with the standard bridge. */
   499	export function mountMcpApp<T>(opts: { devMock: T; App: FC }): void {
   500		const { devMock, App: View } = opts;
   501		createRoot(document.getElementById("root") as HTMLElement).render(
   502			<Provider devMock={devMock}>
   503				<View />
   504			</Provider>,
   505		);
   506	}

