const r=await tools.exec_command({
 cmd:`head -n -1 src/mcp-apps/_shared/host.test.tsx > src/mcp-apps/_shared/host.review.test.tsx
cat >> src/mcp-apps/_shared/host.review.test.tsx <<'EOF'
	it("review probe retries hydration when an edit waits on a failing restore", async () => {
		const compatParent: CompatParent = Object.assign(new EventTarget(), {
			location: { origin: "https://chatgpt.com" },
		});
		Object.defineProperty(window, "parent", {
			configurable: true,
			value: compatParent,
		});
		Object.defineProperty(window, "openai", {
			configurable: true,
			value: {
				widgetState: {
					privateContent: {
						lobuViewSnapshot: {
							version: 1,
							data: { title: "Cached race card" },
						},
					},
				},
				toolResponseMetadata: {
					mcp_tool_result: {
						_meta: {
							"lobu/mcp-app-snapshot-capability": "review-race-token",
						},
					},
				},
			},
		});
		let resolveFirst: ((value: { isError: true }) => void) | undefined;
		const firstRestore = new Promise<{ isError: true }>((resolve) => {
			resolveFirst = resolve;
		});
		let restoreCount = 0;
		bridge.callServerTool.mockImplementation(async ({ name }) => {
			if (name === "restore_lobu_app_result") {
				restoreCount += 1;
				if (restoreCount === 1) return firstRestore;
				return {
					isError: false,
					structuredContent: {
						found: true,
						tool_name: "query_sdk",
						data: { title: "Restored race card" },
						view_state: { "table.page": 1 },
					},
				};
			}
			if (name === "save_lobu_app_state") {
				return { isError: false, structuredContent: { saved: true } };
			}
			return { isError: false };
		});
		const { Provider, useMcpApp } = await import("./host");
		function Probe() {
			const { data, setViewState } = useMcpApp<{ title: string }>();
			return (
				<>
					<span>{data?.title}</span>
					<button type="button" onClick={() => setViewState("details.open", true)}>
						Edit during restore
					</button>
				</>
			);
		}
		render(
			<Provider devMock={{ title: "Development result" }}>
				<Probe />
			</Provider>,
		);
		expect(await screen.findByText("Cached race card")).toBeInTheDocument();
		await waitFor(() => expect(restoreCount).toBe(1));
		fireEvent.click(screen.getByRole("button", { name: "Edit during restore" }));
		await act(() => new Promise((resolve) => window.setTimeout(resolve, 300)));
		await act(async () => {
			resolveFirst?.({ isError: true });
			await firstRestore;
		});
		await waitFor(() => expect(restoreCount).toBeGreaterThanOrEqual(2));
		await waitFor(() =>
			expect(
				bridge.callServerTool.mock.calls.some(
					([request]) => request.name === "save_lobu_app_state",
				),
			).toBe(true),
		);
	});
});
EOF
