	it("review probe replaces a card when the host reuses an id for another tool", async () => {
		const compatParent: CompatParent = Object.assign(new EventTarget(), {
			location: { origin: "https://chatgpt.com" },
		});
		Object.defineProperty(window, "parent", {
			configurable: true,
			value: compatParent,
		});
		bridge.hostContext = {
			toolInfo: { id: "reused-id", tool: { name: "query_sdk" } },
		};
		bridge.callServerTool.mockImplementation(
			async ({ name, arguments: args }) => {
				if (name !== "restore_lobu_app_result") return { isError: false };
				const next = args.tool_name === "query_sql";
				return {
					isError: false,
					structuredContent: {
						found: true,
						tool_name: next ? "query_sql" : "query_sdk",
						data: { title: next ? "New tool card" : "Old tool card" },
						view_state: { "details.open": !next },
					},
				};
			},
		);
		const { Provider, useMcpApp } = await import("./host");
		function Probe() {
			const { data, toolName, viewState } = useMcpApp<{ title: string }>();
			return (
				<>
					<span>{data?.title ?? "No result"}</span>
					<span>{toolName ?? "No tool"}</span>
					<span>open:{String(viewState["details.open"])}</span>
				</>
			);
		}
		render(
			<Provider devMock={{ title: "Development result" }}>
				<Probe />
			</Provider>,
		);
		expect(await screen.findByText("Old tool card")).toBeInTheDocument();
		expect(screen.getByText("open:true")).toBeInTheDocument();
		bridge.hostContext = {
			toolInfo: { id: "reused-id", tool: { name: "query_sql" } },
		};
		act(() => {
			for (const handler of bridge.listeners.get("hostcontextchanged") ?? []) {
				handler({ theme: "light" });
			}
		});
		expect(await screen.findByText("New tool card")).toBeInTheDocument();
		expect(screen.getByText("open:false")).toBeInTheDocument();
		expect(screen.queryByText("Old tool card")).not.toBeInTheDocument();
	});
});
